<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/functions.php';
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$pdo=null;$rows=[];$error='';try{$pdo=get_db('ijin');$rows=$pdo->query("SELECT no_hp,pesan,status FROM batal_praktek_detil_wa WHERE (status IS NULL OR status='') AND no_hp IS NOT NULL AND no_hp!='' ORDER BY no_hp LIMIT 5000")->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
$numbers=[];$groups=[];foreach($rows as $row){$hp=trim((string)$row['no_hp']);if($hp==='')continue;$numbers[$hp]=1;$groups[(string)$row['pesan']][]=$hp;}
$lines='';$i=1;foreach($groups as $msg=>$list){$lines.=$i++.'. '.trim($msg)."\n\n";}$message="📢 *Pengumuman RSU Islam Klaten*\n\nAssalâmu'alaikum wr wb\n\n".$lines."Mohon maaf atas ketidaknyamanannya. Terimakasih 😊🙏🏻\n\nWassalamu'alaikum wr wb\n\n*RSU Islam Klaten*";
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ijin WA · <?=h(APP_NAME)?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/style.css"></head><body class="bg-body-tertiary"><nav class="navbar navbar-expand-lg bg-white border-bottom sticky-top"><div class="container py-2"><a class="navbar-brand fw-bold text-success" href="../index.php"><?=h(APP_NAME)?></a><div class="navbar-nav ms-auto"><a class="nav-link" href="../index.php">Dashboard</a><a class="nav-link" href="../lab/index.php">LAB</a><a class="nav-link" href="../lab/report.php">Laporan LAB</a><a class="nav-link active" href="index.php">Ijin WA</a><a class="nav-link" href="report.php">Laporan Ijin</a><a class="nav-link" href="../chat_dokter.php">Chat Dokter</a><a class="nav-link" href="../master.php">Master Data</a><a class="nav-link" href="../settings.php">Template</a><a class="nav-link" href="../report.php">Laporan Reminder</a></div></div></nav><main class="container py-4 py-lg-5"><div class="mb-4"><span class="badge text-bg-warning-subtle text-warning-emphasis mb-2">IJIN DOKTER</span><h1 class="h3">Notifikasi Ijin / Perubahan Praktik</h1><p class="text-secondary mb-0"><?=count($numbers)?> nomor menunggu pengiriman.</p></div><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><div class="card shadow-sm border-0 mb-4"><div class="card-body"><form id="f"><label class="form-label">Nomor Penerima</label><input id="n" class="form-control mb-3" value="<?=h(implode(',',array_keys($numbers)))?>" readonly><label class="form-label">Pesan</label><textarea id="m" class="form-control" rows="13"><?=h($message)?></textarea><button class="btn btn-success mt-3" id="b" <?=$numbers?'':'disabled'?>>Kirim Notifikasi</button></form><div id="o" class="mt-3"></div></div></div><div class="card shadow-sm border-0"><div class="card-body"><h2 class="h5">Kelompok Pesan</h2><div class="table-responsive"><table class="table table-striped table-hover"><thead><tr><th>No</th><th>Pesan</th><th>Jumlah</th></tr></thead><tbody><?php $n=1;foreach($groups as $msg=>$list):?><tr><td><?=$n++?></td><td><?=nl2br(h($msg))?></td><td><?=count($list)?></td></tr><?php endforeach;?></tbody></table></div></div></div></main><script>document.getElementById('f').addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('b'),o=document.getElementById('o');b.disabled=true;b.textContent='Mengirim...';try{const r=await fetch('../services/ijin/api-send.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({numbers:document.getElementById('n').value,message:document.getElementById('m').value})});const j=await r.json();o.innerHTML='<div class="alert '+(j.success?'alert-success':'alert-danger')+'">'+(j.message||JSON.stringify(j))+'</div>'}catch(x){o.innerHTML='<div class="alert alert-danger">'+x.message+'</div>'}finally{b.disabled=false;b.textContent='Kirim Notifikasi'}});</script></body></html>